import{_ as t,o as e,c as a,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const n="/plantuml/68d1afd96b9e7c72.svg",b=JSON.parse('{"title":"Spring的7个使用场景","description":"","frontmatter":{"title":"Spring的7个使用场景","date":"2022-03-31","categories":["开发框架","Spring"],"tags":["Java","Spring"]},"headers":[],"relativePath":"开发框架/Spring的7个使用场景.md","filePath":"开发框架/Spring的7个使用场景.md"}'),o={name:"开发框架/Spring的7个使用场景.md"};function d(s,r,p,l,h,g){return e(),a("div",null,[...r[0]||(r[0]=[i('<h1 id="spring的7个使用场景" tabindex="-1">Spring的7个使用场景 <a class="header-anchor" href="#spring的7个使用场景" aria-label="Permalink to &quot;Spring的7个使用场景&quot;">​</a></h1><p><a href="https://spring.io" target="_blank" rel="noreferrer">Spring官网</a>中描述了Spring能做的7件事，如下所示：</p><img class="diagram-image" src="'+n+'" alt="" width="340" height="415" loading="lazy" decoding="async"><p>下面将简单介绍各场景的概念与其关联的项目。</p><h2 id="一microservices" tabindex="-1">一、<a href="https://spring.io/microservices" target="_blank" rel="noreferrer">Microservices</a> <a class="header-anchor" href="#一microservices" aria-label="Permalink to &quot;一、[Microservices](https://spring.io/microservices)&quot;">​</a></h2><p>微服务（Microservice）是一个小型的、高度自含的、随时可运行的软件实体，多个相互独立的微服务协同工作构成的微服务架构，可以替代掉传统的大而全的单体服务架构，带来更高的灵活性。</p><p>微服务在Spring中涉及到的项目如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>功能</th></tr></thead><tbody><tr><td><a href="https://spring.io/projects/spring-boot" target="_blank" rel="noreferrer">Spring Boot</a></td><td>快速搭建一个微服务（Java微服务的事实标准）</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud" target="_blank" rel="noreferrer">Spring Cloud</a></td><td>使多个微服务更好地支持分布式特性（服务发现、负载均衡、熔断、分布式跟踪、监控等）</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-stream" target="_blank" rel="noreferrer">Spring Cloud Stream</a></td><td>使微服务可以处理实时消息，以构建一个高度可伸缩的、事件驱动的系统</td></tr><tr><td><a href="https://micrometer.io" target="_blank" rel="noreferrer">Micrometer</a></td><td>监控微服务的各项指标</td></tr></tbody></table><h2 id="二reactive" tabindex="-1">二、<a href="https://spring.io/reactive" target="_blank" rel="noreferrer">Reactive</a> <a class="header-anchor" href="#二reactive" aria-label="Permalink to &quot;二、[Reactive](https://spring.io/reactive)&quot;">​</a></h2><p>响应式（Reactive）系统可以实现低延迟与高吞吐，它有几个特性：快速响应（responsive）、可恢复（resilient）、有弹性（elastic）与消息驱动（ message-driven）。响应式处理是一种范式，它可以帮助开发者开发出非阻塞的、异步的应用，这种应用可以处理回压（back-pressure），其中，“回压”是指在应用处理能力达到阀值时的一种反馈现象。</p><p>响应式在Spring中涉及到的项目如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>功能</th></tr></thead><tbody><tr><td><a href="https://projectreactor.io" target="_blank" rel="noreferrer">Reactor</a></td><td>Spring响应式的基础，Spring WebFlux、Spring Data和Spring Cloud Gateway都用到了它</td></tr><tr><td><a href="https://docs.spring.io/spring-framework/docs/current/reference/html/web-reactive.html" target="_blank" rel="noreferrer">Spring WebFlux</a></td><td>非阻塞性Web框架，相对于Spring MVC而言，可以使用更少的资源处理更多的请求</td></tr><tr><td><a href="https://spring.io/projects/spring-data" target="_blank" rel="noreferrer">Spring Data</a></td><td>（原生）支持以响应式的方式访问数据库资源（如MongoDB、Redis 和 Cassandra）</td></tr><tr><td><a href="https://github.com/r2dbc" target="_blank" rel="noreferrer">R2DBC</a></td><td>（三方）支持以响应式的方式访问数据库资源（如Postgres、Microsoft SQL Server、 MySQL、H2和 Google Spanner)）</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-stream" target="_blank" rel="noreferrer">Spring Cloud Stream</a></td><td>支持以响应式的方式访问消息资源（如RabbitMQ和Kafka）</td></tr></tbody></table><h2 id="三cloud" tabindex="-1">三、<a href="https://spring.io/cloud" target="_blank" rel="noreferrer">Cloud</a> <a class="header-anchor" href="#三cloud" aria-label="Permalink to &quot;三、[Cloud](https://spring.io/cloud)&quot;">​</a></h2><p>云（Cloud）原生应用要求微服务在分布式场景中满足<a href="https://12factor.net/zh_cn/" target="_blank" rel="noreferrer">12-Factor </a>，Spring Cloud套件包含了许多让应用程序在云中运行所需的服务（如服务发现、网关、配置、熔断、链路跟踪等）。</p><p>云原生在Spring中涉及到的项目如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>功能</th></tr></thead><tbody><tr><td><a href="https://github.com/Netflix/eureka" target="_blank" rel="noreferrer">Eureka</a></td><td>服务发现</td></tr><tr><td><a href="https://www.consul.io/" target="_blank" rel="noreferrer">Consul</a></td><td>服务发现</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-zookeeper" target="_blank" rel="noreferrer">Zookeeper</a></td><td>服务发现</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-gateway" target="_blank" rel="noreferrer">Spring Cloud Gateway</a></td><td>网关</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-config" target="_blank" rel="noreferrer">Spring Cloud Config</a></td><td>配置</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-circuitbreaker" target="_blank" rel="noreferrer">Spring Cloud Circuit Breaker</a></td><td>熔断</td></tr><tr><td><a href="https://resilience4j.readme.io/docs/getting-started" target="_blank" rel="noreferrer">Resilience4J</a></td><td>熔断</td></tr><tr><td><a href="https://github.com/alibaba/Sentinel/wiki/Circuit-Breaking" target="_blank" rel="noreferrer">Sentinel</a></td><td>熔断</td></tr><tr><td><a href="https://github.com/Netflix/Hystrix/wiki" target="_blank" rel="noreferrer">Hystrix</a></td><td>熔断</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-sleuth" target="_blank" rel="noreferrer">Spring Cloud Sleuth</a></td><td>链路跟踪</td></tr><tr><td><a href="https://zipkin.io/" target="_blank" rel="noreferrer">Zipkin</a></td><td>链路跟踪</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-contract" target="_blank" rel="noreferrer">Spring Cloud Contract</a></td><td>测试</td></tr></tbody></table><h2 id="四web-apps" tabindex="-1">四、<a href="https://spring.io/web-applications" target="_blank" rel="noreferrer">Web apps</a> <a class="header-anchor" href="#四web-apps" aria-label="Permalink to &quot;四、[Web apps](https://spring.io/web-applications)&quot;">​</a></h2><p>使用Spring构建的网页应用（Web apps）去掉了大量样板代码和配置（得益于SpringBoot的支持），它简化了服务端HTML应用、REST接口等的开发。</p><p>网页应用在Spring中涉及到的项目如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>功能</th></tr></thead><tbody><tr><td><a href="https://spring.io/projects/spring-boot" target="_blank" rel="noreferrer">Spring Boot</a></td><td>网页应用脚手架</td></tr><tr><td><a href="https://spring.io/projects/spring-security" target="_blank" rel="noreferrer">Spring Security</a></td><td>网页应用安全支持</td></tr><tr><td><a href="https://spring.io/projects/spring-data" target="_blank" rel="noreferrer">Spring Data</a></td><td>网页应用数据访问支持</td></tr></tbody></table><h2 id="五serverless" tabindex="-1">五、<a href="https://spring.io/why-spring" target="_blank" rel="noreferrer">Serverless</a> <a class="header-anchor" href="#五serverless" aria-label="Permalink to &quot;五、[Serverless](https://spring.io/why-spring)&quot;">​</a></h2><p>无服务器（Serverless）顾名思义，就是指无需关注服务器等基础设施而只需要关注业务逻辑的一种模型，它在一些情况下与FaaS（功能即服务）等价，国内的Serverless实现有腾讯云的“云函数 SCF”与阿里云的“函数计算 FC”。</p><p>无服务器在Spring中涉及到的项目如下：</p><table tabindex="0"><thead><tr><th>项目</th><th>功能</th></tr></thead><tbody><tr><td><a href="https://spring.io/projects/spring-cloud-function" target="_blank" rel="noreferrer">Spring Cloud Function</a></td><td>提供无服务器（FaaS）支持</td></tr></tbody></table><h2 id="六event-driven" tabindex="-1">六、<a href="https://spring.io/event-driven" target="_blank" rel="noreferrer">Event Driven</a> <a class="header-anchor" href="#六event-driven" aria-label="Permalink to &quot;六、[Event Driven](https://spring.io/event-driven)&quot;">​</a></h2><p>事件驱动（Event Driven）也可使称之为消息驱动，每一个事件驱动的系统都是基于消息处理来实现的。</p><table tabindex="0"><thead><tr><th>项目</th><th>功能</th></tr></thead><tbody><tr><td><a href="https://spring.io/projects/spring-cloud-stream" target="_blank" rel="noreferrer">Spring Cloud Stream</a></td><td>提供“Binders”、“Bindings”和“Messages”三个核心概念来帮助更好地连接Kafka与RabbitMQ等消息组件</td></tr><tr><td><a href="https://spring.io/projects/spring-cloud-function" target="_blank" rel="noreferrer">Spring Cloud Function</a></td><td>更好地处理多个消息的输入与输出，如合并、连接等操作</td></tr><tr><td><a href="https://dataflow.spring.io" target="_blank" rel="noreferrer">Spring Cloud Data Flow</a></td><td>提供跨多个云原生平台处理各种数据源的工具</td></tr><tr><td><a href="https://spring.io/projects/spring-amqp" target="_blank" rel="noreferrer">Spring AMQP</a></td><td>支持AMQP（Advanced Message Queuing Protocol，高级消息队列协议）</td></tr><tr><td><a href="https://spring.io/projects/spring-kafka" target="_blank" rel="noreferrer">Spring Kafka</a></td><td>支持Apache Kafka</td></tr></tbody></table><h2 id="七batch" tabindex="-1">七、<a href="https://spring.io/batch" target="_blank" rel="noreferrer">Batch</a> <a class="header-anchor" href="#七batch" aria-label="Permalink to &quot;七、[Batch](https://spring.io/batch)&quot;">​</a></h2><p>批处理（Batch）用于处理大量数据，处理过程中不需要外部交互且不会中断。</p>',29)])])}const f=t(o,[["render",d]]);export{b as __pageData,f as default};
